import { SiteHeader } from '@/react/components/site/SiteHeader'
import { AsciiTrail } from '@/react/components/visuals/AsciiTrail'
import { SiteFooter } from '@/react/components/blocks/SiteFooter'
import { Button } from '@/react/components/ui/Button'
import { HERO_BAND } from '@/lib/effects/light-art'
import { LIGHT_TILE_B, LIGHT_TILE_C } from '@/lib/light-tiles'
import { aboutContent, type AboutContent, type AboutPhoto, aboutSections, type AboutSection } from '@/lib/pages/about'
import { cn } from '@/react/lib/cn'
import { pageSections, imageFit } from '@/lib/image'
import { Fragment, type ReactNode } from 'react'
import type { HeaderMenus } from '@/lib/site-header'

// The site's about and careers page (pages/About/AboutPage, About.module.css): the header; the head centered (the
// title 40/44, 44/48 from 768, at 720px; the lead 32px under it; the White button 56px under that, the full width on
// phones), 128px from the top; a strip of seven 4:5 columns (120px each on phones, overflowing both edges; the width,
// 12px apart, from 768) in front of the site's band of light, which drifts 4% each way over 14s and holds still with
// reduced motion; the story at 720px (a 24/28 subhead over 16/24 paragraphs); the benefits (the subhead, a lead, then
// each group's title beside its list from 640) and the footer. The strip takes your team's photos through `photos`
// (`src` and `alt`); `light` puts one of the site's light tiles in a column, and a tile with neither stays empty.
// `content` replaces the copy (lib/pages/about.ts).
export interface AboutPageProps {
  content?: AboutContent
  /** The header menus' content, pictures included (the live card's `picture`, the use cases' `shots`); Acme by default. */
  menus?: HeaderMenus
  /** The sections to show, in order; all of them in the page order by default (leave one out to omit it). */
  sections?: readonly AboutSection[]
  className?: string
}

const CONTAINER = 'mx-auto w-full max-w-[calc(var(--ds-layout-content)+2*var(--ds-layout-gutter))] px-(--ds-layout-gutter)'
const LIGHT = { b: LIGHT_TILE_B, c: LIGHT_TILE_C }

function Tile({ photo }: { photo: AboutPhoto }) {
  const src = photo.light ? LIGHT[photo.light] : photo.src
  return (
    <li aria-hidden={photo.light || !src ? 'true' : undefined} data-ds-placeholder={src ? undefined : ''} className={cn('relative aspect-4/5 overflow-hidden', photo.light ? 'bg-surface' : 'bg-surface-raised', photo.wide && 'col-span-2 aspect-auto')}>
      {src ? <img src={src} alt={photo.light ? '' : photo.alt ?? ''} decoding="async" className="absolute inset-0 size-full object-cover" style={photo.light ? undefined : imageFit(photo)} /> : null}
    </li>
  )
}

export function AboutPage({ content: c = aboutContent, menus, sections, className }: AboutPageProps) {
  const parts: Record<AboutSection, ReactNode> = {
    head: (
      <section aria-labelledby={`${c.id}-heading`} className="pt-32 text-center">
        <div className={CONTAINER}>
          <h1 id={`${c.id}-heading`} className="mx-auto max-w-180 type-figure text-balance md:text-heading-1">{c.head.lines.join(' ')}</h1>
          <p className="mt-8 type-body-lg text-fg-soft">{c.head.lead}</p>
          <div className="mt-14 flex flex-col md:flex-row md:justify-center">
            <Button href={c.head.primary.href}>{c.head.primary.label}</Button>
          </div>
        </div>
      </section>
    ),
    photos: (
      <section aria-label={c.film} className="relative isolate overflow-clip py-24">
        <span aria-hidden="true" className="ds-about-band" style={{ backgroundImage: `url("${HERO_BAND.picture}")` }} />
        <ul role="list" className="grid grid-cols-[repeat(7,--spacing(30))] justify-center gap-2 md:grid-cols-7 md:gap-3">
          {c.photos.map((photo, i) => <Tile key={i} photo={photo} />)}
        </ul>
      </section>
    ),
    story: (
      <section aria-labelledby={`${c.id}-story`} className="px-(--ds-layout-gutter) pb-24">
        <div className="mx-auto w-full max-w-180">
          <h2 id={`${c.id}-story`} className="mb-8 type-heading-3 text-balance">{c.story.headline}</h2>
          {c.story.paragraphs.map((p) => <p key={p} className="mb-6 type-body text-pretty text-fg last:mb-0">{p}</p>)}
        </div>
      </section>
    ),
    perks: (
      <section id={c.perks.id} aria-labelledby={`${c.id}-perks`} className="px-(--ds-layout-gutter) pb-32">
        <div className="mx-auto w-full max-w-180">
          <h2 id={`${c.id}-perks`} className="mb-2 type-heading-4 font-medium text-balance md:text-heading-3">{c.perks.headline}</h2>
          <p className="mb-16 type-body text-fg">{c.perks.lead}</p>
          <dl className="grid gap-10">
            {c.perks.groups.map((g) => (
              <div key={g.title} className="grid grid-cols-[minmax(0,1fr)] gap-2 sm:grid-cols-[--spacing(60)_minmax(0,1fr)] sm:gap-4">
                <dt className="type-heading-4 font-medium text-fg">{g.title}</dt>
                <dd>
                  <ul role="list" className="grid gap-1 type-body text-fg">
                    {g.items.map((item) => <li key={item}>{item}</li>)}
                  </ul>
                </dd>
              </div>
            ))}
          </dl>
        </div>
      </section>
    ),
  }
  return (
    <div data-ds="about-page" className={cn('isolate bg-surface text-fg', className)}>
      <AsciiTrail mode="page" />
      <style href="ds-about-page" precedence="ds">{css}</style>
      <SiteHeader menus={menus} links={c.shell.header.nav} secondary={c.shell.header.secondary} />
      <main id="main">
        {pageSections(aboutSections, sections).map((k) => <Fragment key={k}>{parts[k]}</Fragment>)}
      </main>
      <SiteFooter columns={c.shell.footer.columns} legal={c.shell.footer.legal} />
    </div>
  )
}

export default AboutPage

const css = `
.ds-about-band {
  position: absolute; inset-block: 0; left: -10%; z-index: -1; width: 120%; pointer-events: none;
  background-position: 50% 50%; background-size: 100% 100%; background-repeat: no-repeat;
  will-change: transform;
  animation: ds-about-band 14s var(--ds-easing-drift) infinite alternate;
}
@keyframes ds-about-band { from { transform: translateX(-4%); } to { transform: translateX(4%); } }
@media (prefers-reduced-motion: reduce) { .ds-about-band { animation: none; } }
`

// The about page's copy (site content/pages/about.ts): the head, the strip of photos (the site's light tiles at both
// ends and Acme placeholders where a team's own photos go), the story and the benefits. Both flavors read this file.

import type { ImageSlot } from '@/lib/image'

// The header's five pages and the sign-in, the footer's six columns and Acme's legal line.
const shell = {
	header: {
		nav: [
			{ label: 'Products', href: '/products' },
			{ label: 'Use cases', href: '/use-cases' },
			{ label: 'Enterprise', href: '/enterprise' },
			{ label: 'Resources', href: '/resources' },
			{ label: 'Pricing', href: '/pricing' },
		],
		secondary: { label: 'Sign in', href: '/sign-in' },
	},
	footer: {
		columns: [
			{ title: 'Products', wide: true, links: [{ label: 'Brands and creators', href: '/products/brand-search' }, { label: 'Media archive', href: '/products/media-search' }, { label: 'Collaborations', href: '/products/creator-collabs' }, { label: 'Creative insights', href: '/products/creative-insights' }, { label: 'Realtime search', href: '/products/realtime-search' }, { label: 'Coming soon', href: '/products' }] },
			{ title: 'Use cases', wide: true, links: [{ label: 'Build your own', href: '/use-cases/build' }, { label: 'Creative research', href: '/use-cases/creative-research' }, { label: 'Paid ads', href: '/use-cases/paid-ads' }, { label: 'Organic social', href: '/use-cases/organic-social' }, { label: 'Competitive analysis', href: '/use-cases/competitive-analysis' }, { label: 'Creator sourcing', href: '/use-cases/creator-sourcing' }] },
			{ title: 'Resources', links: [{ label: 'Templates', href: '/templates' }, { label: 'Docs', href: '/docs' }, { label: 'Blog', href: '/resources/blog' }, { label: 'Articles', href: '/resources/articles' }] },
			{ title: 'Company', links: [{ label: 'Enterprise', href: '/enterprise' }, { label: 'About', href: '/about' }, { label: 'Careers', href: '/about#careers' }, { label: 'Talk to us', href: '/enterprise#talk' }, { label: 'Sign in', href: '/sign-in' }] },
			{ title: 'Legal', links: [{ label: 'Terms', href: '/terms' }, { label: 'Privacy', href: '/privacy' }] },
			{ title: 'Community', links: [{ label: 'X', href: 'https://x.com' }, { label: 'LinkedIn', href: 'https://linkedin.com' }, { label: 'Instagram', href: 'https://instagram.com' }] },
		],
		legal: '© 2026 Acme Inc.',
	},
}

/** One tile in the strip: your photo (`src`, with `alt`, `fit` and `position`), one of the site's light tiles (`light`), or an empty tile. */
export interface AboutPhoto extends ImageSlot {
	/** The site's light tile b or c instead of a photo. */
	light?: 'b' | 'c'
	/** Two columns wide. */
	wide?: boolean
}

export const aboutContent = {
	shell,
	id: 'about',
	head: {
		lines: ['Come help the world', 'look closer'],
		lead: 'We’re looking for people who notice what others miss.',
		primary: { label: 'Join us', href: 'mailto:careers@acme.com' },
	},
	film: 'The team',
	photos: [{ light: 'b' }, { alt: '' }, { alt: '' }, { alt: '', wide: true }, { alt: '' }, { light: 'c' }] as AboutPhoto[],
	story: {
		headline: 'Spyglass is where the internet’s creative comes into focus.',
		paragraphs: [
			'It’s where marketers and their agents come to see what’s working across ads, posts and creators. Now, we’re building the record behind it: every brand, every channel, ready for any agent to search.',
			'We’re a small team that obsesses over craft and moves quickly. Every detail we ship is one we’d want to use ourselves.',
			'Teams in many countries already brief from Spyglass, from founders running their first ads to global agencies.',
			'If you care about craft, curiosity and doing the best work of your career, come build with us.',
		],
	},
	perks: {
		id: 'careers',
		headline: 'Benefits',
		lead: 'We take care of the people doing the work.',
		groups: [
			{ title: 'Focus', items: ['Top-spec hardware', 'Every AI tool you need', 'Lunch on us'] },
			{ title: 'Culture', items: ['Seasonal offsites', 'Team dinners', 'Friday demos'] },
			{ title: 'Care', items: ['Full health cover', 'Generous time off', 'Learning budget'] },
		],
	},
}

export type AboutContent = typeof aboutContent

/** The about page's sections in order; pass `sections` to reorder them or leave some out. */
export const aboutSections = ['head', 'photos', 'story', 'perks'] as const
export type AboutSection = (typeof aboutSections)[number]

// The site's light tiles for the about page's strip (public/brand/light/tile-b.webp and tile-c.webp, 800x1000): the
// brand light as the site pre-made it for a 4:5 tile, embedded so both flavors draw the same pixels.
export const LIGHT_TILE_B = 'data:image/webp;base64,'
export const LIGHT_TILE_C = 'data:image/webp;base64,'

// Joins class names, skipping falsy ones: cn('a', on && 'b', ['c', undefined]). It does not merge conflicting
// utilities (no tailwind-merge), as Vue's class binding does not: the library's classes are written not to compete,
// and a className from the caller is appended after them, as Vue appends a fallthrough class.
export type ClassValue = string | false | null | undefined | 0 | ClassValue[]

export function cn(...values: ClassValue[]): string {
	const out: string[] = []
	for (const v of values) {
		if (!v) continue
		if (Array.isArray(v)) {
			const s = cn(...v)
			if (s) out.push(s)
		}
		else out.push(v)
	}
	return out.join(' ')
}

